"""Project the season curriculum and Episode 1 surfaces from their authored contracts."""
import hashlib
import html
import json
from pathlib import Path
from prepare_season_one import ROOT, OUT, read, write, binding

def e(value):return html.escape(str(value))
def js(value):return json.dumps(value,ensure_ascii=False).replace('<','\\u003c')
CSS='''
:root{--bg:#080f19;--ink:#f6f1e9;--muted:#aabaca;--current:#73ded5;--target:#b6a4ff;--gap:#efbe77;--line:#2b394a;--panel:#111d2b}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 85% 0,#24223e,transparent 42%),var(--bg);color:var(--ink);font:16px/1.6 'Segoe UI',system-ui,sans-serif}a{color:var(--current)}button,input,select{font:inherit}a,button,input,summary,select{outline-offset:5px}main{max-width:1200px;margin:auto;padding:28px}nav{display:flex;justify-content:space-between;gap:20px;font-size:12px;letter-spacing:.16em}nav a{text-decoration:none;color:var(--ink)}header{padding:76px 0 36px;max-width:980px}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.15em;text-transform:uppercase;color:var(--target)}h1{font-size:clamp(42px,6.5vw,78px);line-height:1.02;letter-spacing:-.045em;margin:16px 0 24px}h2{font-size:31px;line-height:1.18;letter-spacing:-.025em;margin:42px 0 18px}h3{font-size:20px;line-height:1.3;margin:0 0 12px}p{max-width:900px}.lead{font-size:21px;color:#ccd2de}small,.muted{color:var(--muted)}.btn,button{display:inline-block;border:1px solid var(--target);background:var(--target);color:#101124;padding:11px 19px;border-radius:8px;font-weight:700;text-decoration:none;cursor:pointer}.btn.secondary{background:transparent;color:var(--ink);border-color:var(--line)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.grid,.reality{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{border:1px solid var(--line);background:var(--panel);padding:24px;border-radius:14px}.reality .card{border-radius:0;border-left:3px solid var(--current)}.reality .target{border:1px dashed var(--target);box-shadow:inset 0 0 24px #b6a4ff0a}.reality .gap{border-color:var(--gap);border-style:dashed}.badge{font-size:11px;letter-spacing:.12em;color:var(--current);font-weight:800}.target .badge{color:var(--target)}.gap .badge{color:var(--gap)}video{display:block;width:100%;aspect-ratio:16/9;background:#000;border:1px solid var(--line);border-radius:14px}.player{display:grid;grid-template-columns:1fr 285px;gap:18px}.chapters{display:grid;gap:6px}.chapters button{background:var(--panel);color:var(--ink);font-weight:500;text-align:left;border:1px solid var(--line);font-size:13px;padding:7px 11px}.chapters button.active{border-color:var(--target);color:var(--target)}.film-meta{font-size:13px;color:var(--muted);margin:12px 0}.episode{position:relative;padding-left:66px}.episode .n{position:absolute;left:22px;top:24px;color:var(--target);font-size:24px;font-weight:800}.episode summary{cursor:pointer;color:var(--current)}.episode p{font-size:14px}.scene{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.case-controls{display:flex;flex-wrap:wrap;gap:8px}.case-controls button{background:transparent;color:var(--ink);border-color:var(--line);font-size:13px;padding:8px 11px}.case-controls button.selected{border-color:var(--target);color:var(--target)}#decision{font-size:40px;line-height:1.1;margin:16px 0;color:var(--target);font-weight:800}#request{font-size:22px}.fact-list{list-style:none;padding:0;font-size:14px}.fact-list li{padding:8px 0;border-bottom:1px solid var(--line)}.route{display:flex;align-items:center;gap:8px;margin:22px 0}.route .node{border:1px dashed var(--target);padding:14px;text-align:center;flex:1}.route .connector{width:35px;border-top:2px dashed var(--target)}.route .effect{opacity:.28}.route.permit .effect{opacity:1;box-shadow:0 0 25px #b6a4ff22}.report{border-left:3px solid var(--target);padding:18px;background:#171d32}.report[hidden]{display:none}.quiz{padding:22px;border:1px solid var(--line);border-radius:12px;margin:12px 0}.option{display:block;padding:10px;border:1px solid var(--line);border-radius:6px;margin:8px 0}.feedback{color:var(--current);min-height:1.6em}.vocab{border-top:1px solid var(--line);padding-top:16px;margin:24px 0;color:var(--muted);font-size:13px}.surface{display:block;text-decoration:none;color:var(--ink)}.surface:hover{border-color:var(--target)}details{margin-top:16px}summary{cursor:pointer}pre{background:#071019;border:1px solid var(--line);padding:20px;border-radius:8px;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.mono{font:12px/1.5 Consolas,monospace;word-break:break-all}footer{margin-top:60px;padding:24px 0;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}.transcript{max-width:850px}.article-meta{margin-top:10px;font-size:12px;color:var(--target)}@media(max-width:900px){.player,.scene{grid-template-columns:1fr}.chapters{grid-template-columns:1fr 1fr}.grid,.reality{grid-template-columns:1fr}main{padding:20px}header{padding-top:48px}h1{font-size:46px}.route .node{font-size:12px;padding:10px}}
'''

def page(title,body,season=False,script=''):
    link='../content-catalog/index.html' if season else '../../season-1/index.html'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><style>{CSS}</style></head><body><main><nav><a href="{link}">SIDEFX / {'CONTENT ESTATE' if season else 'SEASON 1'}</a><span>THE FUTURE OF AGENTIC ENGINEERING</span></nav>{body}<footer>Current evidence • Intended experience • Engineering runway<br>A SideFX training projection. Target simulations run locally and dispatch no live tools.</footer></main>{'<script>'+script+'</script>' if script else ''}</body></html>'''

def save(path,text):
    path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text,encoding='utf-8')

def reality():return '''<div class="reality"><div class="card"><div class="badge">CURRENT / SOURCE EVIDENCE</div><h3>Inspect the decision.</h3><p>Stored expressions return ALLOW or OPERATOR_REQUIRED. Status fields and fixture expectations are available for inspection.</p></div><div class="card target"><div class="badge">TARGET / INTENDED EXPERIENCE</div><h3>Intercept before effects.</h3><p>Resolve capability, authority and mechanic; execute only the permitted request and retain human control.</p></div><div class="card gap"><div class="badge">GAP / FUTURE CLOSURE</div><h3>Prove the live boundary.</h3><p>Bind same-session probes, exact tool-path coverage, operator control, and decision-to-effect testimony.</p></div></div>'''

def simulation_html():
    return '''<section id="simulation"><div class="eyebrow">Target architecture / interactive reference simulation</div><h2>She asked for an inspection. What happens next?</h2><p>Choose a request to inspect the intended decision. These are authored design cases; no tool is invoked.</p><div class="case-controls" id="cases"></div><div class="scene" style="margin-top:20px"><div class="card target"><div class="badge">PENDING REQUEST</div><div id="request"></div><div id="decision" aria-live="polite"></div><p id="reason"></p><p id="next"></p><div class="route" id="route"><div class="node">Request</div><div class="connector"></div><div class="node">Interlock</div><div class="connector"></div><div class="node effect">Effect</div></div><div id="report" class="report" hidden><strong>Illustrative inspection report</strong><br>Candidate reviewed within the admitted inspection scope.<br><strong>Publication remains pending.</strong></div></div><div class="card"><div class="eyebrow">Design assumptions for this case</div><ul id="facts" class="fact-list"></ul><p class="muted">True values represent assumed evidence in this target simulation. They do not certify the current platform.</p></div></div></section>'''

def simulation_js():
    t=read('declarations/episode-01-target-interlock.json')
    return '''const target='''+js(t)+''';
const labels={identityBound:'Exact identities bound',coveredPath:'Tool path covered',liveBoundaryProven:'Same-session boundary proven',operatorRequired:'Separate operator required',legalAlternativeAvailable:'Legal alternative available',withinAuthority:'Requested effect within authority'};
function showCase(c){const facts={...target.baseFacts,...c.facts};const rule=target.rules.find(r=>facts[r.field]===r.equals);const decision=rule?.decision||'HOLD';document.getElementById('request').textContent=c.request;document.getElementById('decision').textContent=decision;document.getElementById('reason').textContent=rule?.reason||'NO_MATCH';document.getElementById('next').textContent=rule?.next||'Resolve exact authority.';document.getElementById('route').classList.toggle('permit',decision==='PERMIT');document.getElementById('report').hidden=decision!=='PERMIT';document.getElementById('facts').replaceChildren(...Object.entries(facts).map(([k,v])=>{const li=document.createElement('li');li.textContent=labels[k]+' — '+(v?'YES':'NO');return li}));document.querySelectorAll('#cases button').forEach(b=>{b.classList.toggle('selected',b.dataset.id===c.id);b.setAttribute('aria-pressed',String(b.dataset.id===c.id))});}
const buttons=target.cases.map(c=>{const b=document.createElement('button');b.textContent=c.title;b.dataset.id=c.id;b.onclick=()=>showCase(c);return b});document.getElementById('cases').append(...buttons);showCase(target.cases[0]);
'''

def quiz_html(d):
    parts=[]
    for i,q in enumerate(d['assessment']):
        options=''.join(f'<label class="option"><input type="radio" name="q{i}" value="{j}"> {e(option)}</label>' for j,option in enumerate(q['options']))
        parts.append(f'<fieldset class="quiz"><legend>{i+1}. {e(q["question"])}</legend>{options}<div class="feedback" id="feedback-{i}" aria-live="polite"></div></fieldset>')
    return '<section id="assessment"><h2>Apply the principle.</h2>'+''.join(parts)+'<button id="grade">Check understanding</button><p id="score" role="status"></p></section>'

def quiz_js(d):return 'const questions='+js(d['assessment'])+''';document.getElementById('grade').onclick=()=>{let score=0,answered=0;questions.forEach((q,i)=>{const selected=document.querySelector('input[name="q'+i+'"]:checked');const ok=selected&&Number(selected.value)===q.correct;if(selected)answered++;if(ok)score++;document.getElementById('feedback-'+i).textContent=(!selected?'Choose an answer. ':ok?'Correct. ':'Revisit the boundary. ')+q.rationale});document.getElementById('score').textContent=score+' / '+questions.length+' correct; '+answered+' answered.'};'''

def main():
    season=read('declarations/season-1.json'); d=read('declarations/episode-01-direction.json');tl=read((OUT/'timeline.json').relative_to(ROOT));gap=read('evaluations/episode-01-platform-gap.json')
    episode_cards=[]
    for ep in season['episodes']:
        contract=read('declarations/capability-content/'+ep['capabilityId']+'.json')
        href='../content-catalog/interlock-agent-operation/index.html'
        action=f'<a class="btn" href="{href}">Watch + train</a>' if ep['number']==1 else '<span class="badge">CURRICULUM READY / FILM PLANNED</span>'
        episode_cards.append(f'<article class="card episode"><span class="n">{ep["number"]:02}</span><h3>{e(ep["title"])}</h3><p>{e(ep["objective"])}</p>{action}<details><summary>Lesson contract</summary><p><strong>Exercise:</strong> {e(ep["exercise"])}</p><p><strong>Takeaway:</strong> {e(ep["takeaway"])}</p><p class="muted">Capability: {e(contract["title"])}<br>{len(contract["scenarioKeys"])} source scenarios</p></details></article>')
    body=f'<header><div class="eyebrow">Season 1 / A SideFX Training Series</div><h1>{e(season["seriesTitle"])}</h1><p class="lead">{e(season["thesis"])}</p><div class="actions"><a class="btn" href="../content-catalog/interlock-agent-operation/index.html">Start Episode 01</a><a class="btn secondary" href="../../declarations/season-1.json">Inspect curriculum</a><a class="btn secondary" href="../agentic-engineering/index.html">Enter the signature class</a></div></header>'+reality()+'<h2>Ten capabilities. One curriculum.</h2><div class="grid">'+''.join(episode_cards)+'</div><h2>The lesson contract</h2><p>'+ ' → '.join(e(x) for x in season['trainingStructure'])+'</p>'
    save(ROOT/'samples/season-1/index.html',page(season['seriesTitle'],body,True))
    mins,seconds=divmod(round(tl['durationSeconds']),60)
    chapters=''.join(f'<button id="{e(c["id"])}" data-start="{c["start"]}">{i+1:02} / {e(c["section"])}</button>' for i,c in enumerate(tl['chapters']))
    player=f'<div class="player"><div><video id="film" controls preload="metadata" poster="thumbnail.jpg"><source src="episode-01.mp4" type="video/mp4"><track default kind="captions" srclang="en" label="English" src="captions.vtt"></video><p class="film-meta">{mins}:{seconds:02} · Ten chapters · Synthetic narration · 1080p · Animated infographic chapters + cinematic stills · Captions use approximate sentence timing</p></div><div class="chapters">{chapters}</div></div>'
    nav=[('Short','The opening question, in 33 seconds.','short.mp4'),('Read','Follow the full lesson and transcript.','article.html'),('Infographic','Compare evidence, target and closure.','infographic.svg'),('Train','Resolve cases and test understanding.','training.html'),('Demo','Explore the target decision boundary.','demo.html'),('Inspect','Source evidence and improvement gaps.','evidence.html'),('Thumbnail','Reuse the episode cover.','thumbnail.jpg'),('Contract','Inspect the content meaning.','../../../declarations/capability-content/interlock-agent-operation.json')]
    nav.append(('Agentic Engineering','Frame the discipline, test an authority boundary and defend your own design.','../../agentic-engineering/index.html'))
    nav.append(('Living circuit','Replay the silver-ball flow and inspect each source-bound entity.','../../capability-pages/interlock-agent-operation/index.html#circuit'))
    nav.append(('Circuit grammar','Inspect current adjudication, intended certification, and all seven scenario boundaries.','../../infographic-grammar/index.html'))
    cards=''.join(f'<a class="card surface" href="{u}"><h3>{e(t)}</h3><span class="muted">{e(desc)}</span></a>' for t,desc,u in nav)
    header=f'<header><div class="eyebrow">The Future of Agentic Engineering / 01</div><h1>{e(d["title"])}</h1><p class="lead">The work should continue. Authority should stay hers.</p><p class="muted">Capability: Interlock Agent Operation</p></header>'
    player_js="const film=document.getElementById('film');const chapterButtons=[...document.querySelectorAll('.chapters button')];chapterButtons.forEach(b=>b.onclick=()=>{film.currentTime=Math.ceil(Number(b.dataset.start)*24)/24;film.scrollIntoView({block:'center'});film.play()});film.addEventListener('timeupdate',()=>chapterButtons.forEach((b,i)=>b.classList.toggle('active',film.currentTime>=Number(b.dataset.start)&&(i===chapterButtons.length-1||film.currentTime<Number(chapterButtons[i+1].dataset.start)))));"
    player_js+="film.addEventListener('loadedmetadata',()=>{const chapter=chapterButtons.find(b=>'#'+b.id===location.hash);if(chapter){film.currentTime=Math.ceil(Number(chapter.dataset.start)*24)/24;film.scrollIntoView({block:'center'})}});"
    player+='<p class="film-meta">Inside the film: <a href="#open-event">00:55 / Current decision circuit</a> · <a href="#evidence">02:27 / Target certification flow</a>. <a href="infographic-edit.receipt.json">Inspect the infographic edit</a>.</p>'
    player_js+="document.querySelectorAll('a[href=\"#open-event\"],a[href=\"#evidence\"]').forEach(a=>a.onclick=event=>{event.preventDefault();history.replaceState(null,'',a.getAttribute('href'));const chapter=chapterButtons.find(b=>'#'+b.id===a.getAttribute('href'));if(chapter){film.currentTime=Math.ceil(Number(chapter.dataset.start)*24)/24;film.scrollIntoView({block:'center'})}});"
    save(OUT/'index.html',page(d['title'],header+player+'<h2>Evidence vs. intended design</h2>'+reality()+'<div class="vocab">Solid lines: current source evidence. Luminous outlines: target architecture. Interrupted boundaries: missing closure.</div>'+simulation_html()+'<h2>One episode. Reusable content.</h2><div class="grid">'+cards+'</div>',script=player_js+simulation_js()))
    save(OUT/'demo.html',page('Episode 01 / Target interlock simulation',header+reality()+'<h2>Follow the intended boundary.</h2>'+simulation_html(),script=simulation_js()))
    save(OUT/'training.html',page('Episode 01 / Training',header+'<p class="lead">'+e(season['episodes'][0]['objective'])+'</p>'+simulation_html()+quiz_html(d),script=simulation_js()+quiz_js(d)))
    transcript=''.join(f'<section id="{c["id"]}"><h2>{i+1:02} / {e(c["section"])}</h2><div class="article-meta">{e(c["reality"])} / {e(c["title"])}</div><p>{e(c["narration"])}</p></section>' for i,c in enumerate(tl['chapters']))
    save(OUT/'article.html',page('Episode 01 / Article and transcript',header+reality()+'<article class="transcript">'+transcript+'</article>'))
    evidence_cards=''.join(f'<div class="card"><h3>{e(item["fact"])}</h3><a href="../../../{item["sourceRef"]["snapshot"]}">Inspect exact snapshot</a><p class="mono">{e(item["sourceRef"]["entryDigest"])}<br>{e(item["sourceRef"]["pointer"])}</p></div>' for item in gap['currentEvidence'])
    gap_cards=''.join(f'<div class="card gap"><span class="badge">{g["id"]}</span><h3>{e(g["missing"])}</h3><p>{e(g["acceptance"])}</p></div>' for g in gap['gaps'])
    save(OUT/'evidence.html',page('Episode 01 / Evidence and engineering runway',header+reality()+'<h2>What the current snapshot establishes</h2><div class="grid">'+evidence_cards+'</div><p>'+e(gap['currentEvidenceLimit'])+'</p><h2>What would close the target experience</h2><div class="grid">'+gap_cards+'</div><div class="actions"><a class="btn secondary" href="../../../evaluations/episode-01-platform-gap.json">Download improvement brief</a><a class="btn secondary" href="reference-simulation.json">Reference simulation results</a><a class="btn secondary" href="infographic-edit.receipt.json">Infographic film provenance</a></div><p>'+e(gap['handoff'])+'</p>'))
    infographic='''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200"><rect width="1200" height="1200" fill="#080f19"/><style>text{font-family:Segoe UI,Arial;fill:#f6f1e9}.c{fill:#73ded5}.t{fill:#b6a4ff}.g{fill:#efbe77}.m{fill:#aabaca}</style><text x="70" y="76" class="t" font-size="21">THE FUTURE OF AGENTIC ENGINEERING / EPISODE 01</text><text x="70" y="153" font-size="51" font-weight="700">Ready to act. Who decides?</text><rect x="70" y="215" width="1060" height="180" rx="15" fill="#111d2b" stroke="#73ded5" stroke-width="3"/><text x="100" y="260" class="c" font-size="21">CURRENT / SOLID EVIDENCE</text><text x="100" y="310" font-size="29">Request → stored decision → ALLOW or OPERATOR_REQUIRED</text><text x="100" y="355" class="m" font-size="22">Decision semantics exist. Live interception is not established here.</text><path d="M600 397 V445 M600 480 V525" stroke="#efbe77" stroke-width="4"/><text x="625" y="468" class="g" font-size="22">Missing pre-effect enforcement</text><rect x="70" y="525" width="1060" height="360" rx="15" fill="#151b30" stroke="#b6a4ff" stroke-width="3" stroke-dasharray="12 8"/><text x="100" y="575" class="t" font-size="21">TARGET / INTENDED EXPERIENCE</text><text x="100" y="632" font-size="28">Attempted effect → interlock → exact authority + mechanic</text><text x="100" y="692" class="t" font-size="26">PERMIT → admitted execution → effect testimony</text><text x="100" y="749" font-size="24">OPERATOR_REQUIRED → authenticated human decision</text><text x="100" y="805" font-size="24">DENY / RESOLVE / HOLD → reason + next legal action</text><text x="100" y="855" class="m" font-size="20">Reference design. No live effects are performed by this simulation.</text><text x="70" y="967" class="g" font-size="23">FUTURE CLOSURE</text><text x="70" y="1016" font-size="25">Same-session deny + permit probes. Exact path coverage.</text><text x="70" y="1063" font-size="25">Protected operator control. Decision-to-effect receipts.</text><text x="70" y="1140" class="t" font-size="24">The work should continue. Authority should stay hers.</text></svg>'''
    save(OUT/'infographic.svg',infographic)
    def stamp(t):
        ms=round(t*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02}.{ms%1000:03}'
    cues=[]
    for c in tl['chapters']:
        sentences=c['narration'].split('. ');duration=c['duration']-1; cursor=c['start'];total=sum(len(s) for s in sentences)
        for sentence in sentences:
            end=cursor+duration*len(sentence)/total
            cues.append(stamp(cursor)+' --> '+stamp(end)+'\n'+sentence.rstrip('.')+'.');cursor=end
    save(OUT/'captions.vtt','WEBVTT\n\n'+'\n\n'.join(cues)+'\n')
    surfaces={'video':'episode-01.mp4','short':'short.mp4','thumbnail':'thumbnail.jpg','article':'article.html','infographic':'infographic.svg','training':'training.html','demo':'demo.html','landing-page':'index.html','evidence-story':'evidence.html'}
    missing=[p for p in surfaces.values() if not (OUT/p).exists()]
    if missing:print('PAGES READY; media outstanding:',', '.join(missing));return
    manifest={'capabilityId':'interlock-agent-operation','contractSha256':hashlib.sha256((ROOT/'declarations/capability-content/interlock-agent-operation.json').read_bytes()).hexdigest(),'status':'COMPILED_FOR_REVIEW','surfaces':{s:{'path':(OUT/p).relative_to(ROOT).as_posix(),'sha256':hashlib.sha256((OUT/p).read_bytes()).hexdigest(),'status':'COMPILED'} for s,p in surfaces.items()}}
    write('outputs/content-products/interlock-agent-operation.json',manifest)
    print('Season hub and Episode 1 nine-surface package compiled.',flush=True)

if __name__=='__main__':main()
